from record import record
record(12,'accept','离子Soret热扩散','十八个成员逐一均在离子导体/电解质中指温度梯度驱动的离子扩散；3和13直接定义，10直接展开同义。11虽否定其主导作用但概念仍同一机制，不能以否定句误判不同概念。')
record(15,'accept','电子载流子数浓度','十六成员都是半导体/导电聚合物的电子载流子数浓度，density与concentration同量；不把电子/空穴具体数值或符号合并，也不延伸到离子浓度。')
record(20,'uncertain','热电化学效应与热刺激去极化术语','除3外十个成员都指温度驱动红氧电位效应，可作为同一机制；TG:P0111完整摘要却为SmCl3/介孔SiO2热刺激去极化及介电理论，缺少红氧反应定义，不能仅凭thermogalvanic同名合并。',[{'definition':'温差驱动红氧热电化学效应','members':[0,1,2,4,5,6,7,8,9,10]},{'definition':'热刺激去极化中称thermogalvanic的效应','members':[3]}])
for i,definition,reason,parts in [
(13,'载流子迁移率及其程度/测量定义','0/1/2/3/4/6/12/13/15/16为通常电子载流子迁移率；5/10/11为高值；7相对较高；8明确增强的Hall迁移率；9为电子比空穴更好；14为OECT提取的器件有效迁移率，不能用同词跨定义闭包。',[('电子载流子迁移率',[0,1,2,3,4,6,12,13,15,16]),('高载流子迁移率',[5,10,11]),('较高载流子迁移率',[7]),('增强的Hall迁移率',[8]),('电子相对空穴更高迁移率',[9]),('OECT器件有效迁移率',[14])]),
(14,'热电化学热电势及混合响应','0/1/2/3/4/5/6/10/11/12/13/14/15均热电化学电池热电势系数；7完整摘要及8/9明确叠加Soret和热电化学效应，总热响应不等同单独电化学系数。',[('热电化学热电势系数',[0,1,2,3,4,5,6,10,11,12,13,14,15]),('热扩散与热电化学混合热电势',[7,8,9])]),
(16,'离子热扩散与质子特例','0至11均电解质离子热扩散/Soret效应，2泛称由本组电解质上下文约束；12特指质子热扩散，保留物种限定。',[('电解质离子Soret热扩散',list(range(12))),('质子热扩散',[12])]),
(17,'活化能按发生过程和载流子分拆','0载流子生成能，1/2/3由电导提取Ag+迁移活化能；4复合电导和热电势活化能；5Cu迁移NEB势垒；6Cu离子传导活化能；7含空位生成贡献；8Ag+微观势垒；9/10电子电导活化能；11Na导电活化能。共同energy词不保证同量。',[('载流子生成活化能',[0]),('Ag+电导迁移表观活化能',[1,2,3]),('电导与热电势活化能组合',[4]),('Cu迁移微观势垒',[5]),('Cu离子电导活化能',[6]),('含空位生成的离子输运活化能',[7]),('Ag+微观迁移势垒',[8]),('电子电导活化能',[9,10]),('Na离子电导活化能',[11])]),
(18,'离子键合与键的离子性','0/2/3/4/7为键合离子性属性；1/6/8/9/10/11为离子键/键合类型；5特指Rb和Fr原子的离子性。键合类型与离子性程度相关但不严格同义。',[('键合的离子性',[0,2,3,4,7]),('离子键合',[1,6,8,9,10,11]),('Rb/Fr离子性',[5])]),
(19,'声子散射、光谱覆盖、强度及增强','0/2/3/4/5/6/7/10一般声子散射过程；1多波长覆盖；8强散射状态；9/11散射增强变化。区分强度状态与变化，不能闭包消除。',[('声子散射',[0,2,3,4,5,6,7,10]),('多波长声子散射',[1]),('强声子散射',[8]),('声子散射增强',[9,11])]),
(21,'非谐性及其高值和比较','1/5/8/9为晶格/声子非谐性一般属性；0/3/4/6/7/10明确高/强晶格非谐性；2为比较greater，未定义达到高值。',[('晶格非谐性',[1,5,8,9]),('强晶格非谐性',[0,3,4,6,7,10]),('较大非谐性',[2])]),
(22,'离子n型热响应与电子n型导电','0/1/2/3/4为离子迁移或界面极化造成负热电响应，完整摘要核实2/3/4；5/6/7/8/9/10为电子为主的半导体n型导电，不可因n-type同名合并。',[('离子负热电响应',[0,1,2,3,4]),('电子n型导电',[5,6,7,8,9,10])])]:record(i,'split',definition,reason,[{'definition':d,'members':m} for d,m in parts])
